-- GÉNÉRÉ par scripts/build-catalog.mjs — ne pas éditer à la main.
-- Idempotent : ré-exécutable après chaque synchronisation du catalogue.
BEGIN;
ON CONFLICT(id) DO UPDATE SET name=excluded.name,category=excluded.category,rarity=excluded.rarity,power_hp=excluded.power_hp,weight_kg=excluded.weight_kg,top_speed_kmh=excluded.top_speed_kmh,handling_score=excluded.handling_score,year=excluded.year,market_value=excluded.market_value,image_url=excluded.image_url,lore=excluded.lore,division=excluded.division,color=excluded.color,shape=excluded.shape,wikidata_id=excluded.wikidata_id,brand=excluded.brand,image_page=excluded.image_page,image_credit=excluded.image_credit;
SELECT setval(pg_get_serial_sequence('public.cards','id'),(SELECT max(id) FROM public.cards));
UPDATE public.profiles p SET collection_score=(SELECT coalesce(sum(c.market_value::bigint*u.quantity*CASE WHEN u.is_foil THEN 2.5 ELSE 1 END),0)::bigint FROM public.user_cards u JOIN public.cards c ON c.id=u.card_id WHERE u.user_id=p.id);
COMMIT;
